// Real PNG atlas pixels, RLE encoded; synchronous browser/Node fallback without DOM.
export function decodeEnemyAtlas(kind = 'skeleton') {
  const atlas = atlases[kind === 'goblin' ? 'goblin' : 'skeleton'];
  const bytes = atob(atlas.runs), data = new Uint8Array(1024 * 640 * 4);
  let target = 0;
  for (let i = 0; i < bytes.length; i += 3) {
    const count = bytes.charCodeAt(i) | bytes.charCodeAt(i + 1) << 8;
    const color = atlas.palette[bytes.charCodeAt(i + 2)];
    for (let j = 0; j < count; j++) { data.set(color, target); target += 4; }
  }
  if (target !== data.length) throw new Error('Invalid enemy atlas pixel data');
  return { data, width: 1024, height: 640 };
}
